function handleSubmit(event) {
  event.preventDefault();
  if (!state) {
    return;
  }
  var text = E.normalizeText(els.gestureInput.value);
  if (text.length < 8) {
    showToast('A gesture needs more than a wish. Give the material a sentence.', 'error');
    els.gestureInput.focus();
    return;
  }
  var latest = state.receipts[state.receipts.length - 1];
  if (latest && latest.kind === selectedTool && latest.text === text) {
    showToast('The world has already received that exact gesture. Change one word, or choose another hand.', 'error');
    return;
  }

  var result;
  try {
    result = E.applyGesture(state, selectedTool, text, new Date().toISOString());
  } catch (error) {
    showToast(error.message || 'The gesture could not be placed.', 'error');
    return;
  }

  state = result.world;
  selectedSeq = result.receipt.seq;
  newSeq = result.receipt.seq;
  writeLocalWorld();
  renderAll(newSeq);
  newSeq = null;
  els.gestureInput.value = '';
  updateInputState();
  queueServerSave();
  playGestureSound(selectedTool);
  els.gestureInput.focus();

  if (result.receipt.pressure) {
    showToast('The world pushed back. A new pressure entered the ledger.');
  } else {
    showToast('The gesture held without opening a new pressure.');
  }
}

function responseFor(kind, analysis, seq) {
  var choices = RESPONSES[kind];
  if (!choices) {
    return 'The world receives the gesture and keeps the receipt. It does not yet know what kind of material this is.';
  }
  return fill(pick(choices, hashInt(analysis.seed + '|response|' + seq)), analysis);
}

function pressureFor(kind, analysis, seq, existing) {
  var pool = (PRESSURES[kind] || []).slice();
  if (analysis.tone === 'law') {
    pool.push('What can bend under the weight of the {p}?');
  } else if (analysis.tone === 'care') {
    pool.push('Who is outside the shelter of the {p}?');
  } else if (analysis.tone === 'wild') {
    pool.push('What shape is the {p} trying to become without permission?');
  } else if (analysis.tone === 'inquiry') {
    pool.push('What answer would make the {p} less interesting?');
  }
  var held = {};
  (existing || []).forEach(function (tension) {
    if (tension && tension.state === 'open') {
      held[tension.text] = true;
    }
  });
  var start = hashInt(analysis.seed + '|pressure|' + seq) % pool.length;
  for (var i = 0; i < pool.length; i += 1) {
    var candidate = fill(pool[(start + i) % pool.length], analysis);
    if (!held[candidate]) {
      return candidate;
    }
  }
  return 'What has changed in the ' + analysis.primary + ' since receipt ' + (seq + 1) + '?';
}

if (!options.tool) {
  fail('Choose a hand with --tool=probe|chisel|beam|boundary|rehearsal.');
}
if (!options.text) {
  fail('A gesture needs --text="…".');
}
if (options.at && isNaN(Date.parse(options.at))) {
  fail('--at must be a valid ISO timestamp.');
}

let sourcePath = options.state;
if (!fs.existsSync(sourcePath)) {
  if (options.explicitState) {
    fail('No world at ' + sourcePath);
  }
  sourcePath = path.join(root, 'world/seed.json');
}
let source;
try {
  source = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));
} catch (error) {
  fail('Could not read ' + sourcePath + ': ' + error.message);
}
const validatedSource = E.validateWorld(source);
if (!validatedSource.ok) {
  fail('The world is invalid: ' + validatedSource.errors[0]);
}

let result;
try {
  result = E.applyGesture(source, options.tool, options.text, options.at || new Date().toISOString());
} catch (error) {
  fail(error.message);
}

function applyGesture(sourceWorld, kind, rawText, now) {
  if (TOOL_KINDS.indexOf(kind) === -1) {
    throw new Error('Unknown tool: ' + kind);
  }
  var text = normalizeText(rawText);
  if (text.length < 8) {
    throw new Error('A gesture needs at least a sentence to meet the material.');
  }
  if (text.length > 600) {
    throw new Error('The material can hold this, but the instrument cannot read more than 600 characters.');
  }

function applyGesture(sourceWorld, kind, rawText, now) {
  if (TOOL_KINDS.indexOf(kind) === -1) {
    throw new Error('Unknown tool: ' + kind);
  }
  var text = normalizeText(rawText);
  if (text.length < 8) {
    throw new Error('A gesture needs at least a sentence to meet the material.');
  }
  if (text.length > 600) {
    throw new Error('The material can hold this, but the instrument cannot read more than 600 characters.');
  }

  var world = clone(sourceWorld);
  var at = now || new Date().toISOString();
  var seq = world.receipts.length;
  var prev = seq === 0 ? ZERO : world.receipts[seq - 1].fingerprint;
  var analysis = analyze(text, kind, seq);
  var response = responseFor(kind, analysis, seq);
  var beamCount = world.receipts.filter(function (receipt) { return receipt.kind === 'beam'; }).length;
  var shouldPressure = (kind === 'beam' && beamCount >= 2) || (hashInt(analysis.seed + '|weather|' + seq) % 3 !== 0);
  var pressure = shouldPressure ? pressureFor(kind, analysis, seq, world.tensions) : null;
  var motif = motifFor(kind, analysis, seq, at);
  var receipt = receiptPayload(seq, kind, text, at, prev);

  receipt.response = response;
  receipt.pressure = pressure;
  receipt.motif = motif;
  world.receipts.push(receipt);

  var effects = TOOLS[kind].effects;
  Object.keys(effects).forEach(function (key) {
    world.facets[key] = clamp(Math.round(world.facets[key] + effects[key]), 0, 100);
  });
  if (pressure) {
    var tension = addTension(world, pressure, seq);
    if (!tension) {
      receipt.pressure = null;
    }
  }
  world.revision = world.receipts.length;
  world.updatedAt = at;
  world.phase = 'awake';
  return { world: world, receipt: receipt };
}

function takeUpPressure(tension) {
  if (!tension) {
    return;
  }
  setTool('probe');
  els.gestureInput.value = tension.text;
  updateInputState();
  els.gestureInput.focus();
  els.gestureInput.setSelectionRange(els.gestureInput.value.length, els.gestureInput.value.length);
  showToast('Pressure taken into the probe. Change it before placing it.');
}

