function renderField(animateSeq) {
  if (!state) {
    return;
  }
  var scene = els.worldScene;
  while (scene.firstChild) {
    scene.removeChild(scene.firstChild);
  }

  var seed = state.id + '|' + state.question + '|' + state.inheritance.sha256;
  var random = mulberry32(E.hashInt(seed));

  scene.appendChild(renderStars(random));

  var graticule = svgEl('g', { 'class': 'graticule' });
  [72, 132, 192, 252].forEach(function (radius) {
    graticule.appendChild(svgEl('circle', {
      cx: CX, cy: CY, r: radius,
      fill: 'none', stroke: 'rgba(239,230,209,.06)', 'stroke-width': '.6',
      'stroke-dasharray': '1 8'
    }));
  });
  for (var spoke = 0; spoke < 12; spoke += 1) {
    var start = polar(spoke * 30, 64);
    var end = polar(spoke * 30, 292);
    appendLine(graticule, start.x, start.y, end.x, end.y, {
      color: 'rgba(239,230,209,.03)', width: '.55'
    });
  }
  for (var tick = 0; tick < 60; tick += 1) {
    var angle = tick * 6;
    var a = polar(angle, 286);
    var b = polar(angle, tick % 5 === 0 ? 296 : 291);
    appendLine(graticule, a.x, a.y, b.x, b.y, {
      color: 'rgba(239,230,209,.13)', width: '.55', opacity: tick % 5 === 0 ? '.8' : '.4'
    });
  }
  scene.appendChild(graticule);
  scene.appendChild(renderCoreHalo());

  var strata = svgEl('g', { 'class': 'strata' });
  state.receipts.forEach(function (receipt) {
    var group = renderStratum(receipt, receipt.seq === selectedSeq);
    if (animateSeq !== null && animateSeq !== undefined && receipt.seq === animateSeq) {
      group.classList.add('is-new');
    }
    strata.appendChild(group);
  });
  scene.appendChild(strata);
  scene.appendChild(renderCoreSigil());

  var open = E.openTensions(state).length;
  if (els.worldSvgDesc) {
    els.worldSvgDesc.textContent = 'A celestial workbench map with ' + state.receipts.length +
      ' chained receipts and ' + open + ' open pressures. The selected gesture is ' +
      (receiptBySeq(selectedSeq) ? KIND_LABELS[receiptBySeq(selectedSeq).kind].toLowerCase() : 'none') + '.';
  }
}

function renderStratum(receipt, selected) {
  var group = svgEl('g', {
    'class': 'stratum stratum-' + receipt.kind + (selected ? ' is-selected' : ''),
    'data-seq': receipt.seq
  });
  group.appendChild(svgEl('title', {}, (KIND_LABELS[receipt.kind] || receipt.kind) + ': ' + receipt.text));
  var color = KIND_COLORS[receipt.kind] || '#96938c';
  var motif = receipt.motif || { angle: 0, radius: 120, label: receipt.kind };
  var angle = Number(motif.angle) || 0;
  var radius = Number(motif.radius) || 120;

  if (receipt.kind === 'memory') {
    renderMemoryStratum(group, receipt, color);
  } else if (receipt.kind === 'kindle') {
    renderKindleStratum(group, receipt, color);
  } else if (receipt.kind === 'probe') {
    renderProbeStratum(group, receipt, color, angle, radius);
  } else if (receipt.kind === 'chisel') {
    renderChiselStratum(group, receipt, color, angle, radius);
  } else if (receipt.kind === 'beam') {
    renderBeamStratum(group, receipt, color, angle, radius);
  } else if (receipt.kind === 'boundary') {
    renderBoundaryStratum(group, receipt, color, angle, radius);
  } else if (receipt.kind === 'rehearsal') {
    renderRehearsalStratum(group, receipt, color, angle, radius);
  }

  group.addEventListener('click', function () {
    selectReceipt(receipt.seq);
  });
  return group;
}
